using System.Text;

namespace AutoFollower;
public sealed record LeanMorphShape(string Name,int VertexCount,string[] Sliders,int MaximumIndex);
public static class LeanMorphInputs
{
    public static Dictionary<string,int> Shapes(LeanExportInputs.Nif nif){Dictionary<string,int> result=new(StringComparer.Ordinal);for(int i=0;i<nif.Types.Length;i++)if(nif.Types[i] is "BSTriShape" or "BSDynamicTriShape" or "BSSubIndexTriShape"){
        var q=new BoundedBinary(nif.Blocks[i]);uint name=q.U32();if(name>=nif.Strings.Length)throw new InvalidDataException("Morph target shape name absent");int extras=q.Count(100000);q.Take(checked(extras*4));q.Take(4+4+52+4+16);int skin=unchecked((int)q.U32());q.Take(8);ulong desc=q.U32()|((ulong)q.U32()<<32);q.U16();int count=q.U16();int data=q.Count();
        if(data==0&&skin>=0){if(skin>=nif.Types.Length||nif.Types[skin] is not ("NiSkinInstance" or "BSDismemberSkinInstance"))throw new InvalidDataException("Morph target skin link invalid");int part=BitConverter.ToInt32(nif.Blocks[skin],4);if(part<0||part>=nif.Types.Length||nif.Types[part]!="NiSkinPartition")throw new InvalidDataException("Morph target partition link invalid");var p=new BoundedBinary(nif.Blocks[part]);p.Count(100000);int size=p.Count(),stride=p.Count(1024);if(stride==0||stride!=(int)(desc&15)*4||size%stride!=0||size/stride>ushort.MaxValue)throw new InvalidDataException("Morph target partition vertex framing invalid");count=size/stride;}
        if(!result.TryAdd(nif.Strings[name],count))throw new InvalidDataException("Duplicate morph target shape name");}return result;}
    public static Dictionary<string,(HashSet<string> Sliders,int Max)> Tri(byte[] bytes){var q=new BoundedBinary(bytes);if(Encoding.ASCII.GetString(q.Take(4))!="PIRT")throw new InvalidDataException("Required BODYTRI is not the compatible SSE packed format");Dictionary<string,(HashSet<string>,int)> result=new(StringComparer.Ordinal);
        for(int kind=0;kind<2&&q.Remaining>0;kind++){int count=q.U16();if(count>1024)throw new InvalidDataException("BODYTRI shape bound");HashSet<string> seen=new(StringComparer.Ordinal);for(int i=0;i<count;i++){string name=Encoding.UTF8.GetString(q.Take(q.U8()));if(name.Length==0||!seen.Add(name))throw new InvalidDataException("BODYTRI duplicate/empty shape");int n=q.U16();HashSet<string> sliders=new(StringComparer.Ordinal);int maximum=-1;for(int j=0;j<n;j++){string slider=Encoding.UTF8.GetString(q.Take(q.U8()));float scale=q.Float();int vertices=q.U16();if(slider.Length==0||!sliders.Add(slider)||!float.IsFinite(scale)||scale<0)throw new InvalidDataException("BODYTRI morph framing invalid");HashSet<int> indices=[];for(int v=0;v<vertices;v++){int index=q.U16();if(!indices.Add(index))throw new InvalidDataException("BODYTRI duplicate vertex index");maximum=Math.Max(maximum,index);q.Take(kind==0?6:4);}}
            if(result.TryGetValue(name,out var old)){old.Item1.UnionWith(sliders);maximum=Math.Max(maximum,old.Item2);result[name]=(old.Item1,maximum);}else result.Add(name,(sliders,maximum));}}
        q.End();return result;
    }
    public static LeanMorphShape[] Compatible(Dictionary<string,int> shapes,Dictionary<string,(HashSet<string> Sliders,int Max)> morphs){List<LeanMorphShape> result=[];foreach(var pair in morphs){if(!shapes.TryGetValue(pair.Key,out int count))continue;if(count==0||pair.Value.Max>=count)throw new InvalidDataException("Installed BODYTRI vertex indices are incompatible with selected winning shape "+pair.Key+": vertices="+count+", maximum morph index="+pair.Value.Max);result.Add(new(pair.Key,count,pair.Value.Sliders.Order().ToArray(),pair.Value.Max));}return result.ToArray();}
}
